# QWCT 5.11 Cloud helper. Save as qwct_pipeline_runner.py in PROJECT ROOT.
# Reviewed source is SHA256 checked. No orders. No network download.
import base64,bz2,contextlib,hashlib,io,json
_qwct511_sha256='b6fbec23fa02efb785228114b35cc52d1b905909ad1afab23d37634a6804d5c5'
_qwct511_output_budget=16000
_qwct511_payload=''
last_raw_output=""
last_error=None
def _qwct511_source():
    raw = bz2.decompress(base64.b64decode(_qwct511_payload, validate=True))
    if hashlib.sha256(raw).hexdigest() != _qwct511_sha256:
        raise ValueError('QWCT_SOURCE_CHECKSUM_MISMATCH: nothing executed')
    return raw.decode('utf-8')

def _qwct511_cost(line):
    return len(json.dumps({'output_type': 'stream', 'name': 'stdout', 'text': line + '\n'}, ensure_ascii=True))

def _qwct511_lines(text, error=None):
    rows = []
    priority = {'D1': 0, 'START': 0, 'END': 0, 'BLOCKED': 1, 'LOADER_ERROR': 0, 'FEATURES_14': 2, 'PIPELINE_EXAMPLE': 2, 'GATES_8': 3, 'M5_COVERAGE': 3, 'BSU': 3}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        label = 'CAPTURED_MESSAGE'
        value = {'message': raw[:200], 'truncated': len(raw) > 200}
        if raw.startswith('QWCT 5.10 '):
            try:
                label, encoded = raw[len('QWCT 5.10 '):].split(' ', 1)
                value = json.loads(encoded)
                if not isinstance(value, dict):
                    raise ValueError('NON_OBJECT_LOG')
            except (ValueError, TypeError):
                label = 'UNPARSED_LOG'
                value = {'message': raw[:200], 'can_trade': False}
        if label == 'FEATURES_14':
            for feature in value.get('features', {}).values():
                detail = feature.pop('detail', {})
                unavailable = {k: v for k, v in detail.items() if v is None}
                if unavailable:
                    feature['unavailable_subfields'] = unavailable
            value['details_omitted_for_notebook_size'] = True
        if label == 'PIPELINE_EXAMPLE':
            for gate in value.get('gates', {}).values():
                reason = gate.get('reason', '')
                if len(reason) > 140:
                    gate['reason'] = reason[:140]
                    gate['reason_truncated'] = True
        line = 'QWCT 5.10 ' + label + ' ' + json.dumps(value, ensure_ascii=False, sort_keys=True)
        rows.append((priority.get(label, 4), len(rows), label, line))
    if error:
        line = 'QWCT 5.10 LOADER_ERROR ' + json.dumps({'reason': error[:250], 'can_trade': False})
        rows.append((0, len(rows), 'LOADER_ERROR', line))
    used = 0
    kept = []
    omitted = {}
    for rank, index, label, line in sorted(rows):
        cost = _qwct511_cost(line)
        if used + cost <= _qwct511_output_budget - 1024:
            kept.append((index, line))
            used += cost
        else:
            omitted[label] = omitted.get(label, 0) + 1
    result = [line for _, line in sorted(kept)]
    if omitted:
        notice = 'QWCT 5.10 OUTPUT_OMITTED ' + json.dumps({'counts': omitted, 'reason': 'NOTEBOOK_SIZE_BUDGET_NOT_A_DATA_PASS', 'can_trade': False}, sort_keys=True)
        end = next((i for i, x in enumerate(result) if x.startswith('QWCT 5.10 END ')), len(result))
        result.insert(end, notice)
    return result

def _qwct511_run():
    global last_raw_output, last_error
    source = _qwct511_source()
    captured = io.StringIO()
    error = None
    try:
        with contextlib.redirect_stdout(captured), contextlib.redirect_stderr(captured):
            exec(compile(source, 'QWCT_5_10_REVIEWED_SOURCE', 'exec'), globals())
    except Exception as exc:
        error = type(exc).__name__ + ': ' + str(exc)
    last_raw_output = captured.getvalue()
    last_error = error
    print('\n'.join(_qwct511_lines(last_raw_output, error)))

def run():
    print("QWCT 5.11 RUNNER: MODULE_LOADED NO_ORDERS NOTEBOOK_STORES_IMPORTS_ONLY")
    _qwct511_run()
